-- D-056. A collector receipt authorizes only its current, sanitized reading HTML.
-- Existing website eligibility and withdrawals are preserved in the legacy view.
ALTER TABLE knowledge_documents ADD COLUMN body_format TEXT NOT NULL DEFAULT 'plain' CHECK(body_format IN('plain','reading_html'));
CREATE TABLE campus_collector_sources (
 source_id TEXT PRIMARY KEY REFERENCES knowledge_sources(id),account_id TEXT NOT NULL UNIQUE,
 enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN(0,1)),since_day TEXT NOT NULL DEFAULT '2026-09-01',
 interval_minutes INTEGER NOT NULL DEFAULT 1440 CHECK(interval_minutes BETWEEN 60 AND 10080),
 requested_at TEXT,approved_by TEXT NOT NULL REFERENCES console_admins(id),
 permission_basis TEXT NOT NULL CHECK(permission_basis='owner_instruction'),updated_at TEXT NOT NULL
);
CREATE TABLE campus_collector_tokens (
 id TEXT PRIMARY KEY,token_hash TEXT NOT NULL UNIQUE,label TEXT NOT NULL,
 source_ids_json TEXT NOT NULL CHECK(json_valid(source_ids_json)),admin_id TEXT NOT NULL REFERENCES console_admins(id),
 created_at TEXT NOT NULL,expires_at_ms INTEGER NOT NULL,revoked_at TEXT,last_seen_at TEXT
);
CREATE TABLE campus_collector_articles (
 document_id TEXT PRIMARY KEY REFERENCES knowledge_documents(id),source_id TEXT NOT NULL REFERENCES campus_collector_sources(source_id),
 canonical_url TEXT NOT NULL UNIQUE,current_hash TEXT NOT NULL CHECK(length(current_hash)=64),
 state TEXT NOT NULL CHECK(state IN('available','suspected_missing','removed')),observed_at TEXT NOT NULL,
 missing_since_ms INTEGER,missing_count INTEGER NOT NULL DEFAULT 0,last_outcome TEXT NOT NULL,
 provenance TEXT NOT NULL CHECK(provenance IN('local_export','publisher_export')),media_omitted INTEGER NOT NULL CHECK(media_omitted IN(0,1)),
 last_changed_at TEXT NOT NULL
);
CREATE INDEX campus_collector_source_articles ON campus_collector_articles(source_id,observed_at);
CREATE TABLE campus_collector_receipts (
 request_id TEXT PRIMARY KEY,token_id TEXT NOT NULL REFERENCES campus_collector_tokens(id),source_id TEXT NOT NULL REFERENCES campus_collector_sources(source_id),
 document_id TEXT NOT NULL,payload_hash TEXT NOT NULL,result_json TEXT NOT NULL CHECK(json_valid(result_json)),created_at TEXT NOT NULL
);
CREATE INDEX campus_collector_receipt_time ON campus_collector_receipts(created_at);
CREATE TABLE campus_collector_heartbeats (
 token_id TEXT PRIMARY KEY REFERENCES campus_collector_tokens(id),mode TEXT NOT NULL CHECK(mode IN('local_exports','publisher_exports')),
 status TEXT NOT NULL CHECK(status IN('idle','syncing','blocked','error')),last_seen_at TEXT NOT NULL,
 imported INTEGER NOT NULL DEFAULT 0,last_error TEXT
);
CREATE TRIGGER campus_collector_receipt_guard BEFORE INSERT ON campus_collector_receipts BEGIN
 SELECT CASE WHEN NOT EXISTS(
  SELECT 1 FROM campus_collector_tokens t JOIN console_admins a ON a.id=t.admin_id
  JOIN campus_collector_sources p ON p.source_id=NEW.source_id JOIN knowledge_sources s ON s.id=p.source_id,json_each(t.source_ids_json) scope
  WHERE t.id=NEW.token_id AND t.revoked_at IS NULL AND t.expires_at_ms>CAST((julianday('now')-2440587.5)*86400000 AS INTEGER)
  AND a.principal_type='human' AND a.role='admin' AND a.status='active' AND scope.value=NEW.source_id AND p.enabled=1
  AND s.console_managed=1 AND s.enabled=1 AND s.archived_at IS NULL AND s.permission_status<>'denied'
  AND s.channel_type IN('wechat_subscription','wechat_service')
 ) THEN RAISE(ABORT,'COLLECTOR_CREDENTIAL_OR_SOURCE_REVOKED') END;
END;
-- View/guard extension and the explicit 78-account policy follow below.

DROP VIEW console_public_documents;
CREATE VIEW console_legacy_public_documents AS SELECT d.* FROM knowledge_documents d JOIN knowledge_sources s ON s.id=d.source_id
 WHERE d.owner_user_id IS NULL AND d.data_domain<>'user_private' AND s.console_managed=1 AND s.source_type<>'user_private' AND s.archived_at IS NULL
 AND d.publication_status='published' AND d.review_status='approved' AND d.workflow_status='approved' AND d.lifecycle_status='active'
 AND d.content_revision>0 AND d.input_hash IS NOT NULL AND d.approved_content_revision=d.content_revision AND d.approved_input_hash=d.input_hash
 AND d.rights_scope IN('metadata_only','excerpt_and_link','licensed_full_text') AND d.content_type<>'unknown'
 AND (d.radar_category IS NOT NULL OR d.knowledge_category IS NOT NULL)
 AND (d.candidate_kind<>'event' OR (d.radar_category IS NOT NULL AND COALESCE(json_extract(d.extracted_fields_json,'$.timeVerified'),0)=1 AND COALESCE(json_extract(d.extracted_fields_json,'$.placeVerified'),0)=1 AND COALESCE(json_extract(d.extracted_fields_json,'$.deadlineVerified'),0)=1 AND julianday(json_extract(d.extracted_fields_json,'$.endAt'))>julianday('now')))
 AND (d.data_domain<>'official_policy' OR s.official_status='verified_official')
 AND (d.valid_until IS NULL OR julianday(d.valid_until)>julianday('now') OR (d.rights_scope='metadata_only' AND d.candidate_kind='knowledge' AND EXISTS(SELECT 1 FROM console_commands m JOIN console_admins a ON a.id=m.admin_id WHERE m.target_id=d.id AND m.target_type='document' AND m.action IN('document.publish','document.classify') AND a.principal_type='human' AND json_extract(m.details_json,'$.manualRevision')=d.content_revision AND json_extract(m.details_json,'$.manualInputHash')=d.input_hash)))
 AND NOT EXISTS(SELECT 1 FROM console_document_controls x WHERE x.document_id=d.id AND (x.hold_reason IS NOT NULL OR x.review_hold IS NOT NULL))
 AND (
  (s.enabled=1 AND s.permission_status<>'denied' AND (d.rights_scope='metadata_only' AND d.candidate_kind='knowledge' AND EXISTS(SELECT 1 FROM console_commands m JOIN console_admins a ON a.id=m.admin_id WHERE m.target_id=d.id AND m.target_type='document' AND m.action IN('document.publish','document.classify') AND a.principal_type='human' AND json_extract(m.details_json,'$.manualRevision')=d.content_revision AND json_extract(m.details_json,'$.manualInputHash')=d.input_hash)) AND EXISTS(SELECT 1 FROM console_document_controls c WHERE c.document_id=d.id AND c.last_publication_mode='manual'))
  OR (NOT EXISTS(SELECT 1 FROM console_publication_policies p WHERE p.source_id=s.id AND p.enabled=0) AND s.enabled=1 AND s.permission_status<>'denied' AND d.rights_scope='metadata_only' AND d.candidate_kind='knowledge'
   AND EXISTS(SELECT 1 FROM console_document_controls x WHERE x.document_id=d.id AND x.last_publication_mode='auto' AND x.auto_policy_version=0)
   AND EXISTS(SELECT 1 FROM console_content_checks c WHERE c.document_id=d.id AND c.content_revision=d.content_revision AND c.input_hash=d.input_hash AND c.policy_version=0 AND c.rule_version='console-metadata-v1' AND c.outcome='pass'))
  OR (
   (s.enabled=1 OR (s.retain_history=1 AND s.affiliation_status='confirmed')) AND s.verification_status='verified' AND s.permission_status='approved' AND s.authorization_status='approved'
   AND NOT EXISTS(SELECT 1 FROM console_document_controls x WHERE x.document_id=d.id AND x.last_publication_mode='auto' AND NOT EXISTS(SELECT 1 FROM console_publication_policies p WHERE p.source_id=d.source_id AND p.enabled=1 AND p.version=x.auto_policy_version AND p.expires_at_ms>CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) AND EXISTS(SELECT 1 FROM console_content_checks c WHERE c.document_id=d.id AND c.content_revision=d.content_revision AND c.input_hash=d.input_hash AND c.policy_version=p.version AND c.rule_version='console-completeness-v1' AND c.outcome='pass')))
   AND (s.governance_checked_at IS NULL OR (s.affiliation_status='confirmed' AND (s.operating_status='active' OR s.retain_history=1)))
   AND NOT EXISTS(SELECT 1 FROM source_collection_policies p WHERE p.source_id=d.source_id AND s.manual_policy_version=0 AND p.expires_at_ms<=CAST((julianday('now')-2440587.5)*86400000 AS INTEGER))
   AND (s.manual_policy_version=0 OR s.manual_policy_expires_at_ms>CAST((julianday('now')-2440587.5)*86400000 AS INTEGER))
  )
 );


CREATE VIEW console_public_documents AS
 SELECT d.* FROM console_legacy_public_documents d WHERE NOT EXISTS(SELECT 1 FROM campus_collector_articles c WHERE c.document_id=d.id)
 UNION ALL
 SELECT d.* FROM knowledge_documents d JOIN campus_collector_articles c ON c.document_id=d.id JOIN campus_collector_sources p ON p.source_id=c.source_id JOIN knowledge_sources s ON s.id=d.source_id JOIN console_admins a ON a.id=p.approved_by
 WHERE d.source_id=c.source_id AND p.enabled=1 AND s.enabled=1 AND s.console_managed=1 AND s.archived_at IS NULL AND s.permission_status<>'denied' AND s.channel_type IN('wechat_subscription','wechat_service')
 AND a.principal_type='human' AND a.role='admin' AND a.status='active'
 AND d.owner_user_id IS NULL AND d.data_domain='approved_life_experience' AND d.publication_status='published' AND d.lifecycle_status='active' AND d.workflow_status='approved' AND d.review_status='approved'
 AND d.body_format='reading_html' AND length(d.body)>0 AND d.rights_scope='licensed_full_text' AND d.candidate_kind='knowledge' AND d.content_type<>'unknown'
 AND c.state IN('available','suspected_missing') AND c.current_hash=d.input_hash AND d.approved_input_hash=d.input_hash AND d.approved_content_revision=d.content_revision AND d.content_revision>0
 AND ((d.radar_category IS NULL)<>(d.knowledge_category IS NULL)) AND d.valid_until IS NULL
 AND NOT EXISTS(SELECT 1 FROM console_document_controls x WHERE x.document_id=d.id AND (x.hold_reason IS NOT NULL OR x.review_hold IS NOT NULL));

DROP TRIGGER console_document_publish_guard;
CREATE TRIGGER console_document_publish_guard BEFORE UPDATE ON knowledge_documents WHEN NEW.publication_status='published' AND NEW.owner_user_id IS NULL AND NEW.data_domain<>'user_private' AND NOT EXISTS(SELECT 1 FROM campus_collector_articles c JOIN campus_collector_sources p ON p.source_id=c.source_id JOIN knowledge_sources s ON s.id=p.source_id JOIN console_admins a ON a.id=p.approved_by WHERE c.document_id=NEW.id AND c.source_id=NEW.source_id AND c.current_hash=NEW.input_hash AND c.state IN('available','suspected_missing') AND p.enabled=1 AND s.enabled=1 AND s.console_managed=1 AND s.archived_at IS NULL AND s.permission_status<>'denied' AND s.channel_type IN('wechat_subscription','wechat_service') AND a.principal_type='human' AND a.role='admin' AND a.status='active' AND NEW.body_format='reading_html' AND NEW.rights_scope='licensed_full_text' AND NEW.candidate_kind='knowledge' AND NEW.data_domain='approved_life_experience' AND NEW.lifecycle_status='active' AND NEW.review_status='approved' AND NEW.workflow_status='approved' AND NEW.valid_until IS NULL) BEGIN
 SELECT CASE WHEN NEW.review_status<>'approved' OR NEW.workflow_status<>'approved' OR NEW.lifecycle_status<>'active' OR (NEW.valid_until IS NOT NULL AND NEW.valid_until<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND NOT (NEW.rights_scope='metadata_only' AND NEW.candidate_kind='knowledge' AND EXISTS(SELECT 1 FROM console_commands m JOIN console_admins a ON a.id=m.admin_id WHERE m.target_id=NEW.id AND m.target_type='document' AND m.action IN('document.publish','document.classify') AND a.principal_type='human' AND json_extract(m.details_json,'$.manualRevision')=NEW.content_revision AND json_extract(m.details_json,'$.manualInputHash')=NEW.input_hash AND m.expected_version=OLD.version)))
 OR NOT EXISTS(SELECT 1 FROM knowledge_sources WHERE id=NEW.source_id AND console_managed=1 AND enabled=1 AND ((verification_status='verified' AND permission_status='approved') OR (permission_status<>'denied' AND (NEW.rights_scope='metadata_only' AND NEW.candidate_kind='knowledge' AND EXISTS(SELECT 1 FROM console_commands m JOIN console_admins a ON a.id=m.admin_id WHERE m.target_id=NEW.id AND m.target_type='document' AND m.action IN('document.publish','document.classify') AND a.principal_type='human' AND json_extract(m.details_json,'$.manualRevision')=NEW.content_revision AND json_extract(m.details_json,'$.manualInputHash')=NEW.input_hash AND m.expected_version=OLD.version))) OR (NEW.rights_scope='metadata_only' AND NEW.candidate_kind='knowledge' AND permission_status<>'denied' AND (EXISTS(SELECT 1 FROM console_document_controls x WHERE x.document_id=NEW.id AND x.last_publication_mode='auto' AND x.auto_policy_version=0) OR EXISTS(SELECT 1 FROM console_commands c WHERE c.target_id=NEW.id AND c.expected_version=OLD.version AND c.action='document.metadata_publish')))) AND archived_at IS NULL AND (NEW.data_domain<>'official_policy' OR official_status='verified_official'))
 THEN RAISE(ABORT,'CONSOLE_CONTENT_NOT_READY') END;
 SELECT CASE WHEN NEW.candidate_kind='event' AND (COALESCE(json_extract(NEW.extracted_fields_json,'$.timeVerified'),0)<>1 OR COALESCE(json_extract(NEW.extracted_fields_json,'$.placeVerified'),0)<>1 OR json_extract(NEW.extracted_fields_json,'$.startAt') IS NULL OR NEW.campus_scope='unknown'
 OR COALESCE(json_extract(NEW.extracted_fields_json,'$.deadlineVerified'),0)<>1) THEN RAISE(ABORT,'CONSOLE_CONTENT_NOT_READY') END;
END;


